<script setup lang="ts">
import DecorationStylePicker from './DecorationStylePicker.vue'
import {decorationBuiltinUrl} from '../../../../api/src/core/decoration-assets.mjs'
import {changeActivityStyle} from '../../../../api/src/core/decoration-reference.mjs'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import type {DecorationBlock,DecorationItem,DecorationOptions,DecorationRoute} from '../../../../api/src/core/decoration-types'
import {decorationOptions} from '../../../../api/src/core/decoration-options.mjs'
import {hotspotStyle,richMediaHtml} from '../../../../api/src/core/decoration-components.mjs'
import ConsolePagePathPicker from './ConsolePagePathPicker.vue'
import {defineConsoleAsyncComponent} from '../../utils/async-component'
const ConsoleRichTextEditor=defineConsoleAsyncComponent(()=>import('./ConsoleRichTextEditor.vue'),'富文本编辑器')
import ImageSelectTile from './ImageSelectTile.vue'
import DecorationVisualPicker from './DecorationVisualPicker.vue'
import MaterialPicker from './MaterialPicker.vue'
import DecorationSettingRange from './DecorationSettingRange.vue'
import DecorationColorField from './DecorationColorField.vue'
const props=defineProps<{disabled?:boolean;routes:DecorationRoute[];imageUrl:(id:string)=>string;materialEndpoint:string}>()
const block=defineModel<DecorationBlock>({required:true})
const o=computed(()=>decorationOptions(block.value)),picker=ref(false),imageTarget=shallowRef<{imageId:string|null;builtin?:string}|null>(null)
function set(key:keyof DecorationOptions,value:unknown){if(!props.disabled)block.value.options={...o.value,[key]:value}}
function pick(target:{imageId:string|null}){if(props.disabled)return;imageTarget.value=target;picker.value=true}
function picked(file:{id:string}){if(!props.disabled&&imageTarget.value){imageTarget.value.imageId=file.id;delete imageTarget.value.builtin}}
const asset=(item:{imageId:string|null;builtin?:string})=>item.imageId?props.imageUrl(item.imageId):decorationBuiltinUrl(item.builtin)
function clearImage(item:{imageId:string|null;builtin?:string}){if(!props.disabled){item.imageId=null;delete item.builtin}}
const titleStyles=[{value:'simple',label:'风格1',image:'/decoration/variants/text/style1.png'},{value:'detailed',label:'风格2',image:'/decoration/variants/text/style2.png'}]
const activityTitles=[1,2,3,5,6].map((n,i)=>({value:'style-'+(i+1),label:'风格'+(i+1),image:'/decoration/variants/active_cube/title_style'+n+'.png'}))
const activityStyles=[1,2,3,4].map(n=>({value:'style-'+n,label:'风格'+n,image:'/decoration/variants/active_cube/block_style'+n+'.png'}))
const searchStyles=[1,2].map(n=>({value:String(n),label:'风格'+n,image:'/decoration/variants/carousel_search/style_'+n+'.png'}))
function titleStyle(value:string){set('activityTitleStyle',value);set('titleColor',value==='style-4'?'#ffffff':'#f91700');set('subtitleColor',value==='style-4'?'#333333':value==='style-5'?'#999999':'#ffffff');set('subtitleBackground',['style-4','style-5'].includes(value)?'#ffffff':'#fb792f');set('subtitleBackgroundEnd',['style-4','style-5'].includes(value)?'#ffffff':'#f91700')}
function add(items:DecorationItem[],hot=false){if(props.disabled||items.length>=(block.value.type==='float'?3:10))return;items.push({id:crypto.randomUUID(),label:hot?'热区 '+(items.length+1):'新入口',text:'',imageId:null,target:'',...(hot?{left:5,top:5,width:30,height:25}:{})})}
function remove(items:DecorationItem[],index:number){if(!props.disabled)items.splice(index,1)}
function move(items:DecorationItem[],index:number,offset:number){if(props.disabled||index+offset<0||index+offset>=items.length)return;const [item]=items.splice(index,1);items.splice(index+offset,0,item!)}
const hotWords=computed({get:()=>o.value.hotWords.join('\n'),set:value=>set('hotWords',value.split('\n').map(v=>v.trim()).filter(Boolean).slice(0,50))})
const richHtml=computed({get:()=>block.value.html||'',set:html=>{block.value.html=html}})
const displayHtml=(html:string)=>richMediaHtml(html,props.imageUrl)
const storeHtml=(html:string)=>html.replace(/(?:https?:\/\/[^/"\s]+)?\/api\/v1\/admin\/tenants\/[^/"\s]+\/materials\/[^/"\s]+\/([0-9a-f-]{36})\/content\?purpose=library/gi,'/decoration-media/$1')
let drawing:{x:number;y:number;item:DecorationItem;id:number}|null=null
function point(event:PointerEvent){const r=(event.currentTarget as HTMLElement).getBoundingClientRect();return {x:Math.max(0,Math.min(100,(event.clientX-r.left)/r.width*100)),y:Math.max(0,Math.min(100,(event.clientY-r.top)/r.height*100))}}
function start(event:PointerEvent){if(props.disabled||event.button!==0||block.value.items.length>=10||!block.value.imageId)return;event.preventDefault();const p=point(event);add(block.value.items,true);const item=block.value.items.at(-1)!;Object.assign(item,{left:p.x,top:p.y,width:.1,height:.1});drawing={...p,item,id:event.pointerId};(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId)}
function draw(event:PointerEvent){if(!drawing||drawing.id!==event.pointerId)return;const p=point(event);Object.assign(drawing.item,{left:Math.min(p.x,drawing.x),top:Math.min(p.y,drawing.y),width:Math.max(.1,Math.abs(p.x-drawing.x)),height:Math.max(.1,Math.abs(p.y-drawing.y))})}
function end(){if(drawing&&((drawing.item.width||0)<1||(drawing.item.height||0)<1)){const i=block.value.items.indexOf(drawing.item);if(i>=0)block.value.items.splice(i,1)}drawing=null}
function setRect(item:DecorationItem,key:'left'|'top'|'width'|'height',value:number){if(props.disabled)return;item[key]=value;if((item.left||0)+(item.width||0)>100)item.width=100-(item.left||0);if((item.top||0)+(item.height||0)>100)item.height=100-(item.top||0)}
</script>
<template><div class="extended-content">
  <template v-if="block.type==='text'">
    <DecorationStylePicker :model-value="o.titleStyle" label="标题风格" :items="titleStyles" :disabled="disabled" @update:model-value="set('titleStyle',$event);$event==='detailed'&&set('showMore',true)"/>
    <UFormField label="标题链接"><ConsolePagePathPicker v-model="block.target" :options="routes" allow-empty :disabled="disabled"/></UFormField>
    <template v-if="o.titleStyle==='detailed'"><DecorationColorField :model-value="o.subtitleColor" label="副标题颜色" :disabled="disabled" @update:model-value="set('subtitleColor',$event)"/><DecorationSettingRange :model-value="o.subtitleSize" label="副标题字号" :min="12" :max="20" :disabled="disabled" @update:model-value="set('subtitleSize',$event)"/><label class="toggle">显示更多<USwitch :model-value="o.showMore" :disabled="disabled" @update:model-value="set('showMore',$event)"/></label><template v-if="o.showMore"><UFormField label="更多文字"><ConsoleInput :model-value="o.moreText" :maxlength="12" :disabled="disabled" @update:model-value="set('moreText',$event)"/></UFormField><UFormField label="更多链接"><ConsolePagePathPicker :model-value="o.moreTarget" :options="routes" allow-empty :disabled="disabled" @update:model-value="set('moreTarget',$event)"/></UFormField></template></template>
  </template>
  <template v-if="block.type==='divider'"><UFormField label="线条样式"><USelect :model-value="o.lineStyle" :items="[{label:'实线',value:'solid'},{label:'虚线',value:'dashed'},{label:'点线',value:'dotted'}]" :disabled="disabled" class="w-full" @update:model-value="set('lineStyle',$event)"/></UFormField><DecorationSettingRange :model-value="o.lineWidth" label="线条粗细" :min="1" :max="10" :disabled="disabled" @update:model-value="set('lineWidth',$event)"/><DecorationColorField v-model="block.color" label="线条颜色" :disabled="disabled"/></template>
  <template v-if="['membership','member-level','member-overview'].includes(block.type)">
    <DecorationVisualPicker v-model:image-id="block.imageId" v-model:icon="block.icon" :fallback-image="block.builtin?imageUrl(block.builtin):undefined" label="会员权益图标" :image-url="imageUrl" :disabled="disabled" :fallback-icon="block.type==='membership'?'crown':'award'" @pick="pick(block)"/>
    <UFormField label="标题"><ConsoleInput v-model="block.title" :maxlength="30" :disabled="disabled"/></UFormField>
    <UFormField label="副标题"><ConsoleInput v-model="block.text" :maxlength="60" :disabled="disabled" placeholder="选填"/></UFormField><UFormField label="按钮文字"><ConsoleInput :model-value="block.options?.buttonText||''" :maxlength="12" :disabled="disabled" placeholder="查看权益" @update:model-value="set('buttonText',$event)"/></UFormField><UFormField label="跳转页面"><ConsolePagePathPicker v-model="block.target" :options="routes" allow-empty :disabled="disabled"/></UFormField>
  </template>
  <p v-if="block.type==='assets'" class="help">至少保留一项资产。登录后显示当前账户数据，积分充值与余额充值分别进入对应充值页，页面内可查看资产明细；充值前需登录。编辑预览使用示例数据。</p>
  <template v-if="block.type==='rich-text'"><ConsoleRichTextEditor v-model="richHtml" :endpoint="materialEndpoint" purpose="library" label="富文本正文" :image-source="imageUrl" :display-html="displayHtml" :store-html="storeHtml" :maxlength="10000" :disabled="disabled"/></template>
  <template v-if="block.type==='hot-area'"><UFormField label="背景图片"><ImageSelectTile :src="asset(block)" label="热区背景" :disabled="disabled" :removable="!!(block.imageId||block.builtin)" @select="pick(block)" @remove="clearImage(block)"/></UFormField><p class="help">在图片上拖动框选热区，也可以在下方精确调整位置和大小。</p><div class="hotspot-editor" @pointerdown="start" @pointermove="draw" @pointerup="end" @pointercancel="end"><img :src="block.imageId?imageUrl(block.imageId):'/decoration/image-placeholder.svg'" alt="热区编辑图片" draggable="false"><span v-for="(item,index) in block.items" :key="item.id" :style="hotspotStyle(item)">{{index+1}}</span></div></template>
  <template v-if="block.type==='activity'"><DecorationStylePicker :model-value="o.activityTitleStyle" label="标题风格" :items="activityTitles" :disabled="disabled" @update:model-value="titleStyle"/><UFormField label="活动标题"><ConsoleInput v-model="block.title" :maxlength="30" :disabled="disabled"/></UFormField><UFormField label="副标题链接"><ConsolePagePathPicker :model-value="o.subtitleTarget" :options="routes" allow-empty :disabled="disabled" @update:model-value="set('subtitleTarget',$event)"/></UFormField><UFormField label="活动副标题"><ConsoleInput v-model="block.text" :maxlength="50" :disabled="disabled"/></UFormField><UFormField v-if="o.activityTitleStyle==='style-5'" label="标题图片"><ImageSelectTile :src="asset(block)" label="活动标题图片" :disabled="disabled" :removable="!!(block.imageId||block.builtin)" @select="pick(block)" @remove="clearImage(block)"/></UFormField><UFormField label="标题链接"><ConsolePagePathPicker v-model="block.target" :options="routes" allow-empty :disabled="disabled"/></UFormField><DecorationStylePicker :model-value="o.activityStyle" label="板块风格" :items="activityStyles" :disabled="disabled" @update:model-value="!disabled&&changeActivityStyle(block,$event)"/></template>
  <template v-if="block.type==='float'"><UFormField label="悬浮位置"><USelect :model-value="o.floatPosition" :items="[{label:'右下',value:'bottom-right'},{label:'左下',value:'bottom-left'},{label:'右上',value:'top-right'},{label:'左上',value:'top-left'}]" :disabled="disabled" class="w-full" @update:model-value="set('floatPosition',$event)"/></UFormField><DecorationSettingRange :model-value="o.floatOffset" label="上下偏移" :max="100" :disabled="disabled" @update:model-value="set('floatOffset',$event)"/><DecorationSettingRange :model-value="o.floatSide" label="左右边距" :min="-10" :max="15" :disabled="disabled" @update:model-value="set('floatSide',$event)"/><DecorationSettingRange :model-value="o.floatSize" label="图片尺寸" :min="30" :max="100" :disabled="disabled" @update:model-value="set('floatSize',$event)"/><DecorationSettingRange :model-value="o.iconRadius" label="图片圆角" :max="50" :disabled="disabled" @update:model-value="set('iconRadius',$event)"/></template>
  <template v-if="block.type==='search-box'"><UFormField label="搜索提示"><ConsoleInput v-model="block.title" :maxlength="20" :disabled="disabled"/></UFormField><UFormField label="搜索目标"><ConsolePagePathPicker v-model="block.target" :options="routes" :disabled="disabled"/></UFormField></template><template v-if="block.type==='search'"><UFormField label="搜索提示"><ConsoleInput v-model="block.title" :maxlength="20" :disabled="disabled"/></UFormField><UFormField label="搜索目标"><ConsolePagePathPicker v-model="block.target" :options="routes" :disabled="disabled"/></UFormField><DecorationStylePicker :model-value="String(o.searchVariant)" label="搜索风格" :items="searchStyles" :disabled="disabled" @update:model-value="set('searchVariant',Number($event))"/><DecorationVisualPicker v-model:image-id="block.imageId" v-model:icon="block.icon" label="搜索品牌图标" :image-url="imageUrl" :disabled="disabled" @pick="pick(block)"/><label class="toggle">显示返回箭头<USwitch :model-value="o.headerBack" :disabled="disabled" @update:model-value="set('headerBack',$event)"/></label><template v-if="o.searchVariant===2"><UFormField label="搜索副标题"><ConsoleInput v-model="block.text" :maxlength="20" :disabled="disabled"/></UFormField><label class="toggle">地址定位<USwitch :model-value="o.headerPosition" :disabled="disabled" @update:model-value="set('headerPosition',$event)"/></label></template><label class="toggle">滚动时吸顶<USwitch :model-value="o.searchFixed" :disabled="disabled" @update:model-value="set('searchFixed',$event)"/></label><UFormField label="轮播热词（一行一个）"><UTextarea v-model="hotWords" :rows="3" :disabled="disabled" class="w-full"/></UFormField><DecorationSettingRange :model-value="o.hotWordInterval" label="热词切换间隔" :min="1000" :max="10000" :step="500" unit="ms" :disabled="disabled" @update:model-value="set('hotWordInterval',$event)"/><label class="toggle">显示分类标签<USwitch :model-value="o.showSearchTabs" :disabled="disabled" @update:model-value="set('showSearchTabs',$event)"/></label>
    <section v-if="o.showSearchTabs"><div class="section-title"><h3>分类标签</h3><UButton size="xs" variant="outline" color="neutral" :disabled="disabled||(block.tabs||[]).length>=10" @click="block.tabs??=[];add(block.tabs!)">添加标签</UButton></div><div v-for="(item,index) in block.tabs" :key="item.id" class="item"><ConsoleInput v-model="item.label" :maxlength="20" :disabled="disabled" aria-label="分类名称"/><ConsolePagePathPicker v-model="item.target" :options="routes" :disabled="disabled"/><UButton size="xs" variant="ghost" color="error" :disabled="disabled" @click="remove(block.tabs!,index)">移除标签</UButton></div></section>
    <label class="toggle">显示轮播图片<USwitch :model-value="o.showSearchBanner" :disabled="disabled" @update:model-value="set('showSearchBanner',$event)"/></label><template v-if="o.showSearchBanner"><DecorationSettingRange v-model="block.height" label="轮播图片高度" :min="40" :max="400" :disabled="disabled"/><label class="toggle">自动轮播<USwitch :model-value="o.autoplay" :disabled="disabled" @update:model-value="set('autoplay',$event)"/></label><DecorationSettingRange :model-value="o.interval" label="图片切换间隔" :min="1000" :max="10000" :step="500" unit="ms" :disabled="disabled" @update:model-value="set('interval',$event)"/></template>
  </template>
  <template v-if="['hot-area','activity','float','search'].includes(block.type)&&(block.type!=='search'||o.showSearchBanner)"><div class="section-title"><h3>{{block.type==='hot-area'?'热区列表':block.type==='float'?'浮动按钮':block.type==='search'?'轮播图片':'活动卡片'}}</h3><UButton size="xs" icon="i-lucide-plus" variant="outline" color="neutral" :disabled="disabled||block.items.length>=(block.type==='float'?3:10)" @click="add(block.items,block.type==='hot-area')">添加</UButton></div>
    <article v-for="(item,index) in block.items" :key="item.id" class="item"><div class="item-bar"><strong>{{index+1}}</strong><UButton size="xs" variant="ghost" color="neutral" icon="i-lucide-chevron-up" :disabled="disabled||index===0" aria-label="上移" @click="move(block.items,index,-1)"/><UButton size="xs" variant="ghost" color="neutral" icon="i-lucide-chevron-down" :disabled="disabled||index===block.items.length-1" aria-label="下移" @click="move(block.items,index,1)"/><UButton size="xs" variant="ghost" color="error" :disabled="disabled" @click="remove(block.items,index)">移除</UButton></div><UFormField label="名称"><ConsoleInput v-model="item.label" :maxlength="20" :disabled="disabled"/></UFormField>
      <template v-if="block.type==='hot-area'"><DecorationSettingRange v-for="field in [{key:'left',label:'左侧位置'},{key:'top',label:'顶部位置'},{key:'width',label:'宽度'},{key:'height',label:'高度'}] as const" :key="field.key" :model-value="item[field.key]||0" :label="field.label" :min="field.key==='width'||field.key==='height'?1:0" :max="100" :step="1" unit="%" :disabled="disabled" @update:model-value="setRect(item,field.key,$event)"/></template>
      <DecorationVisualPicker v-else-if="block.type==='float'" v-model:image-id="item.imageId" v-model:icon="item.icon" :label="item.label+'图标'" :image-url="imageUrl" :disabled="disabled" @pick="pick(item)"/><ImageSelectTile v-else :src="asset(item)" :label="'图片 '+(index+1)" :disabled="disabled" :removable="!!(item.imageId||item.builtin)" @select="pick(item)" @remove="clearImage(item)"/>
      <template v-if="block.type==='activity'"><UFormField label="副标题"><ConsoleInput v-model="item.text" :maxlength="50" :disabled="disabled"/></UFormField><UFormField label="按钮文字"><ConsoleInput v-model="item.buttonText" :maxlength="12" placeholder="去看看" :disabled="disabled"/></UFormField><DecorationColorField :model-value="item.buttonBackground||'#fea715'" label="按钮背景" :disabled="disabled" @update:model-value="item.buttonBackground=$event"/><DecorationColorField :model-value="item.buttonBackgroundEnd||'#fe1e00'" label="按钮渐变末色" :disabled="disabled" @update:model-value="item.buttonBackgroundEnd=$event"/><DecorationColorField :model-value="item.subtitleColor||'#999999'" label="副标题文字" :disabled="disabled" @update:model-value="item.subtitleColor=$event"/><template v-if="o.activityStyle==='style-4'"><DecorationColorField :model-value="item.subtitleBackground||'#f3dac5'" label="副标题背景" :disabled="disabled" @update:model-value="item.subtitleBackground=$event"/><DecorationColorField :model-value="item.subtitleBackgroundEnd||'#f3dac5'" label="副标题渐变末色" :disabled="disabled" @update:model-value="item.subtitleBackgroundEnd=$event"/></template><DecorationColorField :model-value="item.color||'#303133'" label="文字颜色" :disabled="disabled" @update:model-value="item.color=$event"/><DecorationColorField :model-value="item.background||'#fff8f2'" label="卡片背景" :disabled="disabled" @update:model-value="item.background=$event"/><DecorationColorField :model-value="item.backgroundEnd||'#ffffff'" label="渐变末色" :disabled="disabled" @update:model-value="item.backgroundEnd=$event"/></template>
      <UFormField label="跳转链接"><ConsolePagePathPicker v-model="item.target" :options="routes" :allow-empty="block.type==='search'" :disabled="disabled"/></UFormField>
    </article>
  </template>
  <template v-if="block.type==='showcase'"><section v-for="(panel,index) in block.panels" :key="panel.id"><h3>{{index===0?'左侧模块':'右侧模块'}}</h3><UFormField label="模块标题"><ConsoleInput v-model="panel.title" :maxlength="30" :disabled="disabled"/></UFormField><UFormField label="标题图片（可选）"><ImageSelectTile :src="asset(panel)" label="模块标题图片" :disabled="disabled" :removable="!!(panel.imageId||panel.builtin)" @select="pick(panel)" @remove="clearImage(panel)"/></UFormField><UFormField label="副标题"><ConsoleInput v-model="panel.text" :maxlength="50" :disabled="disabled"/></UFormField><DecorationColorField v-model="panel.color" label="标题颜色" :disabled="disabled"/><DecorationColorField v-model="panel.background" label="背景颜色" :disabled="disabled"/><DecorationColorField v-model="panel.backgroundEnd" label="渐变末色" :disabled="disabled"/><article v-for="(item,i) in panel.items" :key="item.id" class="item"><h4>图片 {{i+1}}</h4><ImageSelectTile :src="asset(item)" label="展播图片" :disabled="disabled" :removable="!!(item.imageId||item.builtin)" @select="pick(item)" @remove="clearImage(item)"/><UFormField label="按钮文字"><ConsoleInput v-model="item.label" :maxlength="20" :disabled="disabled"/></UFormField><DecorationColorField :model-value="item.color||'#ffffff'" label="按钮文字颜色" :disabled="disabled" @update:model-value="item.color=$event"/><DecorationColorField :model-value="item.background||'#f5443e'" label="按钮背景" :disabled="disabled" @update:model-value="item.background=$event"/><DecorationColorField :model-value="item.backgroundEnd||'#f5443e'" label="按钮渐变末色" :disabled="disabled" @update:model-value="item.backgroundEnd=$event"/><ConsolePagePathPicker v-model="item.target" :options="routes" :disabled="disabled"/></article></section></template>
  <MaterialPicker v-model:open="picker" :endpoint="materialEndpoint" portal="tenant" purpose="library" @select="picked"/>
</div></template>
<style scoped>.extended-content,.extended-content section{display:grid;gap:18px;min-width:0}.extended-content:empty{display:none}.extended-content section+section{border-top:1px solid var(--ui-border);padding-top:22px}.extended-content h3{font-size:13px;font-weight:600}.help{font-size:12px;line-height:1.7;color:var(--ui-text-muted)}.toggle,.section-title{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px}.item{display:grid;gap:14px;border:1px solid var(--ui-border);border-radius:8px;padding:14px;min-width:0}.item-bar{display:flex;align-items:center;gap:3px}.item-bar strong{margin-right:auto;font-size:12px}.hotspot-editor{position:relative;touch-action:none;cursor:crosshair;user-select:none}.hotspot-editor img{display:block;width:100%;pointer-events:none}.hotspot-editor span{position:absolute;border:1px solid #2563eb;background:#2563eb30;box-sizing:border-box;color:#1d4ed8;pointer-events:none;font-size:12px}</style>
